import { useState } from 'react';
import { Pressable, StyleSheet, Text, View } from 'react-native';

export default function App() {
  const [cajas, setCajas] = useState(0);
  return (
    <View style={styles.pantalla}>
      <Text style={styles.titulo}>Cajas cargadas: {cajas}</Text>
      <Pressable style={styles.boton} onPress={() => setCajas(cajas + 1)}>
        <Text style={styles.textoBoton}>Sumar una caja</Text>
      </Pressable>
    </View>
  );
}

const fabric = {
  createNode(reactTag, viewName, rootTag, props) {
    note(`createNode  tag=${reactTag} ${viewName} ${JSON.stringify(props)}`);
    return { tag: reactTag, viewName, props };
  },
  appendChild(padre, hijo) {
    note(`appendChild  ${padre.viewName}#${padre.tag} <- ${hijo.viewName}#${hijo.tag}`);
  },
  completeRoot(root, hijos) {
    note(`completeRoot  hijos=${hijos.map(c => c.viewName + '#' + c.tag).join(',')}`);
  },
  // ...el resto de los métodos que React llama, sin hacer nada
};
globalThis.nativeFabricUIManager = fabric; // el nombre que busca el renderizador de React Native

